def find_possible_sequence(n: int, values: List[int]) -> List[int]:
    possible_sequence: List[int] = []

    # Find all possible sequence of length n from the given list of numbers
    for i in range(1, n + 1):
        current_sequence = list(range(1, i + 1))
        if all(x <= current_sequence[0] for x in values):
            if i == 1:
                possible_sequence.append(current_sequence)
            else:
                previous_sequence = find_possible_sequence(i - 1, values)
                for num in previous_sequence:
                    current_sequence.append(num)
                possible_sequence.append(current_sequence)

    # Find the sequence with the maximum sum
    max_sum = max(possible_sequence, key=lambda x: sum(x))

    return max_sum

