def check_palindrome(s):
    # Initialize pointers to the start and end of the string
    start = 0
    end = len(s) - 1

    while start < end:
        # If the character at the start is '0', swap it with the character at the end
        if s[start] == '0':
            s = s[:start] + '1' + s[end+1:]
            # Update the start pointer to 'end'
            start = end
        # If the character at the start is '1', no need to swap
        else:
            # If the characters at the start and end are the same, move both forward
            if s[start] == s[end]:
                start += 1
                end -= 1
            # If the characters at the start and end are different, we can break
            else:
                break

    # Check if the modified string is a palindrome
    if s == s[::-1]:
        return True
    else:
        return False

