    """Creates a new list by taking the first k elements of each in-place list."""
    return lists[:k] + [list(zip_longest(*lists[k:]))]

def make_fortran(lists, k):
    """Creates a new list by taking the first k elements of each in-place list, in Fortran order."""
    return lists[:k] + list(zip_longest(*lists[k:]))

