def solve():
    n, m = map(int, input().split())
    rows, cols = [0, 0] * 2  # Initialize rows and columns
    visited = [[False for _ in range(m)] for _ in range(2)]

    # Find the first pair of columns with the same row
    for i in range(m):
        for j in range(n):
            if visited[j][i]:
                continue
            if j == 0:
                rows[i] = 1
            elif j == 1:
                rows[i] = 0
            visited[j][i] = True
            if i == 0:
                cols[i] = 1
            elif i == 1:
                cols[i] = 0

    # Check all possible moves
    for i in range(m):
        x, y = map(int, input().split())
        x = min(x, rows[i])
        y = min(y, cols[i])

        # Check if the position is occupied
        if x == 0 and y == 0:
            continue
        if i == 0:
            rows[x] = 0
        elif i == 1:
            rows[x] = 1
        visited[x][y] = True

        # Check if the position is not occupied
        if not visited[y][x]:
            return "YES"

