    if n == 1 and m == 1:
        return 1
    total = n + m - 2
    min_cost = 100000000
    for cost in range(total + 1):
        min_cost = min(min_cost, cost)
        new_n, new_m = n - 1, m - 1
        while new_n >= 1 and new_m >= 1:
            if new_n < new_m:
                new_n += 1
